 choice("CPU mode",{"Standard","Economy"},0); choice("Signal check",{"Full amp","Dry input","Preamp only","No feedback","Phase inverter only"},0); choice("Amp",{"Marshall","Peavey 5150","Rectifier","Pittbull","EVH"}); choice("Marshall",{"Stock","Jose pre EQ","HBE","Snorkler","Jose post EQ","Molecular (prototype)"}); choice("Rectifier",{"Orange","Red","Multi-Watt"},1); choice("EVH",{"Blue","Red","EL34 Blue","Stealth Blue","Stealth Red"}); choice("Power amp",{"Marshall","Peavey","Rectifier Vintage","Rectifier Modern","VHT","EVH","Mini Rectifier","AC30","AC50","SLO"}); p.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{"Link power",1},"Link power",true)); choice("Tube",{"EL34","EL84","6L6GC","Native"},3); choice("Cold bias",{"Native","1.5k","4.7k","10k","22k","39k","47k"}); choice("Bypass cap",{"Native","Off","0.68u","1u","22u"}); choice("Jose clip",{"Off","20V","12V","Asymmetric"},1);
