 using SA=AP::SliderAttachment;using CA=AP::ComboBoxAttachment;using BA=AP::ButtonAttachment;
 struct Knob {juce::Label label;juce::Slider slider;std::unique_ptr<SA> attachment;};
 struct Choice {juce::Label label;juce::ComboBox box;std::unique_ptr<CA> attachment;};
 struct Toggle {juce::ToggleButton button;std::unique_ptr<BA> attachment;};
 std::array<Knob,9> knobs;std::array<Choice,12> choices;std::array<Toggle,4> toggles;
 juce::TextButton load{"Load cabinet IR"};std::unique_ptr<juce::FileChooser> chooser;
 Editor(Processor& proc):AudioProcessorEditor(proc),p(proc){
 const char* ks[]={"Gain","Gain 2","Bass","Mid","Treble","Presence","Master","Output","Volume"};
 const char* cs[]={"Amp","Marshall","Rectifier","EVH","Power amp","Tube","Cold bias","Bypass cap","Jose clip","CPU mode","Signal check","Clip position"};
 const char* ts[]={"Link power","Spongy","Tube rectifier","Cabinet"};
 for(size_t i=0;i<knobs.size();++i){auto& k=knobs[i];k.label.setText(ks[i],juce::dontSendNotification);k.label.setJustificationType(juce::Justification::centred);k.slider.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);k.slider.setTextBoxStyle(juce::Slider::TextBoxBelow,false,70,22);addAndMakeVisible(k.label);addAndMakeVisible(k.slider);k.attachment=std::make_unique<SA>(p.state,ks[i],k.slider);}
 for(size_t i=0;i<choices.size();++i){auto& c=choices[i];c.label.setText(cs[i],juce::dontSendNotification);auto* param=dynamic_cast<juce::AudioParameterChoice*>(p.state.getParameter(cs[i]));if(param)c.box.addItemList(param->choices,1);addAndMakeVisible(c.label);addAndMakeVisible(c.box);c.attachment=std::make_unique<CA>(p.state,cs[i],c.box);}
 for(size_t i=0;i<toggles.size();++i){auto& t=toggles[i];t.button.setButtonText(ts[i]);addAndMakeVisible(t.button);t.attachment=std::make_unique<BA>(p.state,ts[i],t.button);}
 addAndMakeVisible(load);load.onClick=[this]{juce::Component::SafePointer<Editor> safe(this);chooser=std::make_unique<juce::FileChooser>("Choose cabinet impulse response",juce::File{},"*.wav;*.aiff");chooser->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles,[safe](const juce::FileChooser& f){if(safe!=nullptr&&f.getResult().existsAsFile())safe->p.loadIR(f.getResult());});};
 setResizable(true,true);setResizeLimits(760,650,1500,1000);setSize(880,700);startTimerHz(8);timerCallback();
 }
 void timerCallback() override {int amp=(int)p.v("Amp");for(int i=1;i<=3;++i){bool show=(i==1&&amp==0)||(i==2&&amp==2)||(i==3&&amp==4);choices[i].label.setVisible(show);choices[i].box.setVisible(show);}bool jose=amp==0&&(int)p.v("Marshall")!=0;knobs[1].slider.setVisible(jose);knobs[1].label.setVisible(jose);choices[8].box.setVisible(jose);choices[8].label.setVisible(jose);choices[11].label.setVisible(false);choices[11].box.setVisible(false);const int architecture=(int)p.v("Marshall");const bool nativeVolume=jose&&(architecture==1||architecture==4);knobs[1].label.setVisible(jose&&architecture!=5);knobs[1].slider.setVisible(jose&&architecture!=5);knobs[8].label.setVisible(nativeVolume);knobs[8].slider.setVisible(nativeVolume);knobs[6].label.setVisible(!nativeVolume);knobs[6].slider.setVisible(!nativeVolume);resized();choices[4].box.setEnabled(p.v("Link power")<.5f);}
 void paint(juce::Graphics& g) override {g.fillAll(juce::Colour(0xff171b20));g.setColour(juce::Colour(0xffe2b77b));g.setFont(24.f);g.drawText("ULTIMATE HIGH GAIN",20,8,getWidth()-40,40,juce::Justification::centredLeft);g.setFont(14.f);for(auto item:std::array<std::pair<int,const char*>,3>{{{58,"PREAMP / VOICING"},{300,"POWER AMP"},{482,"CABINET / ENGINE"}}})g.drawText(item.second,20,item.first,getWidth()-40,22,juce::Justification::centredLeft);}
